-- SQLite 3 import script for ChatExport_2026-10-14.
-- Run: sqlite3 membership-history.sqlite3 < membership-history.sqlite3.sql
-- All 252 HTML pages were scanned. Service messages do not expose exact timestamps in this export.
-- date_hint is the preceding date separator, not a timestamp.
-- IMPORTANT: "invite" means an invitation record, not proof that the invited account joined.
PRAGMA foreign_keys=ON;
BEGIN TRANSACTION;
CREATE TABLE export_metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE service_events(
 event_id INTEGER PRIMARY KEY,
 source_page INTEGER NOT NULL,
 telegram_message_id INTEGER NOT NULL,
 date_hint TEXT,
 timestamp_utc TEXT,
 event_type TEXT NOT NULL,
 actor_text TEXT,
 subject_text TEXT,
 raw_text TEXT NOT NULL,
 UNIQUE(source_page,telegram_message_id)
);
CREATE INDEX idx_events_date ON service_events(date_hint);
CREATE INDEX idx_events_type_date ON service_events(event_type,date_hint);
CREATE INDEX idx_events_actor ON service_events(actor_text);
CREATE INDEX idx_events_subject ON service_events(subject_text);
CREATE INDEX idx_events_message_id ON service_events(telegram_message_id);
COMMIT;
